import React from 'react';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  Brush,
  ReferenceLine
} from 'recharts';

// Fungsi helper untuk memformat tanggal
const formatDate = (dateString) => {
  const date = new Date(dateString);
  // Cek apakah tanggal valid
  if (isNaN(date.getTime())) return dateString;

  return date.toLocaleDateString('id-ID', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  });
};

// Fungsi helper untuk memformat angka sebagai mata uang
const formatCurrency = (value, currencySymbol = 'Rp') => {
  if (typeof value !== 'number') return '-';
  return `${currencySymbol} ${value.toLocaleString('id-ID')}`;
};

// Custom Tooltip komponen
const CustomTooltip = ({ active, payload, label, currencySymbol }) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;
    const priceChange = data.previousClose ? data.Close - data.previousClose : 0;
    const percentChange = data.previousClose ? (priceChange / data.previousClose) * 100 : 0;
    const isPositive = priceChange >= 0;

    return (
        <div className="custom-tooltip" style={{ 
          backgroundColor: 'rgba(255, 255, 255, 0.9)',
          padding: '10px',
          border: '1px solid #ddd',
          borderRadius: '5px'
        }}>
          <p className="tooltip-date" style={{ fontWeight: 'bold', marginBottom: '5px' }}>
            {formatDate(data.Date || data.Datetime)}
          </p>
          <div className="tooltip-data">
            <p>
              <span className="tooltip-label">Buka:</span>
              <span className="tooltip-value">{formatCurrency(data.Open, currencySymbol)}</span>
            </p>
            <p>
              <span className="tooltip-label">Tertinggi:</span>
              <span className="tooltip-value">{formatCurrency(data.High, currencySymbol)}</span>
            </p>
            <p>
              <span className="tooltip-label">Terendah:</span>
              <span className="tooltip-value">{formatCurrency(data.Low, currencySymbol)}</span>
            </p>
            <p>
              <span className="tooltip-label">Tutup:</span>
              <span className="tooltip-value">{formatCurrency(data.Close, currencySymbol)}</span>
            </p>
            {data.previousClose && (
              <p>
                <span className="tooltip-label">Perubahan:</span>
                <span className="tooltip-value" style={{ color: isPositive ? '#4CAF50' : '#E53935' }}>
                  {isPositive ? '+' : ''}{formatCurrency(priceChange, currencySymbol)} ({isPositive ? '+' : ''}{percentChange.toFixed(2)}%)
                </span>
              </p>
            )}
            <p>
              <span className="tooltip-label">Volume:</span>
              <span className="tooltip-value">{data.Volume.toLocaleString('id-ID')}</span>
            </p>
          </div>
        </div>
    );
  }

  return null;
};

// Kustom dot yang akan menampilkan warna berbeda berdasarkan perbandingan dengan titik sebelumnya
const CustomizedDot = (props) => {
  const { cx, cy, payload } = props;
  
  if (payload.isPositive) {
    return <circle cx={cx} cy={cy} r={3} fill="#4CAF50" />;
  }
  
  return <circle cx={cx} cy={cy} r={3} fill="#E53935" />;
};

const StockChart = ({ data, currencySymbol = 'Rp' }) => {
  // Pastikan data tidak kosong
  if (!data || data.length === 0) {
    return (
        <div className="chart-container">
          <p>Tidak ada data yang tersedia untuk ditampilkan</p>
        </div>
    );
  }

  // Persiapkan data untuk chart (urutkan berdasarkan tanggal)
  const sortedData = [...data].sort((a, b) => {
    const dateA = new Date(a.Date || a.Datetime);
    const dateB = new Date(b.Date || b.Datetime);
    return dateA - dateB; // Ascending order for chart
  });
  
  // Tambahkan informasi previousClose dan isPositive untuk setiap titik data
  const chartData = sortedData.map((item, index) => {
    if (index === 0) {
      return {
        ...item,
        previousClose: null,
        isPositive: true // Default untuk titik pertama
      };
    }
    
    const previousClose = sortedData[index - 1].Close;
    const isPositive = item.Close >= previousClose;
    
    return {
      ...item,
      previousClose,
      isPositive
    };
  });

  // Fungsi untuk menentukan apakah menampilkan semua titik data
  const shouldShowAllTicks = chartData.length <= 30;

  // Format ticks pada sumbu X
  const formatXAxis = (tickItem) => {
    const date = new Date(tickItem);
    if (isNaN(date.getTime())) return tickItem;

    // Format singkat (DD/MM) jika banyak data
    if (chartData.length > 30) {
      return date.toLocaleDateString('id-ID', {
        day: '2-digit',
        month: '2-digit'
      });
    }

    // Format lengkap jika sedikit data
    return date.toLocaleDateString('id-ID', {
      day: '2-digit',
      month: '2-digit',
      year: '2-digit'
    });
  };

  // Cari nilai min dan max untuk sumbu Y
  const minValue = Math.min(...chartData.map(item => item.Low));
  const maxValue = Math.max(...chartData.map(item => item.High));

  // Tambahkan sedikit margin untuk visualisasi yang lebih baik
  const yAxisDomain = [
    minValue - (minValue * 0.01), // 1% lebih rendah dari minimum
    maxValue + (maxValue * 0.01)  // 1% lebih tinggi dari maksimum
  ];

  // Buat segmen data untuk membedakan area naik dan turun
  const segments = [];
  let currentSegment = [];
  let currentDirection = null;

  chartData.forEach((point, index) => {
    if (index === 0) {
      currentSegment.push(point);
      currentDirection = true; // Asumsikan awal positif
    } else {
      const isPositive = point.Close >= chartData[index - 1].Close;
      
      // Jika arah berubah, buat segmen baru
      if (isPositive !== currentDirection) {
        segments.push({
          data: [...currentSegment],
          isPositive: currentDirection
        });
        currentSegment = [chartData[index - 1], point]; // Tambahkan titik tumpang tindih untuk kontinuitas
        currentDirection = isPositive;
      } else {
        currentSegment.push(point);
      }
    }
    
    // Tambahkan segmen terakhir
    if (index === chartData.length - 1 && currentSegment.length > 0) {
      segments.push({
        data: [...currentSegment],
        isPositive: currentDirection
      });
    }
  });

  return (
      <div className="chart-container">
        <div className="chart-wrapper" style={{ position: 'relative' }}>
          <ResponsiveContainer width="100%" height={400}>
            <LineChart
                data={chartData}
                margin={{
                  top: 20,
                  right: 30,
                  left: 20,
                  bottom: 50
                }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" />
              <XAxis
                  dataKey="Date"
                  tickFormatter={formatXAxis}
                  tick={{ fontSize: 12 }}
                  interval={shouldShowAllTicks ? 0 : 'preserveStartEnd'}
                  angle={-45}
                  textAnchor="end"
                  height={70}
              />
              <YAxis
                  domain={yAxisDomain}
                  tickFormatter={(value) => formatCurrency(value, currencySymbol)}
                  tick={{ fontSize: 12 }}
                  width={80}
              />
              <Tooltip
                  content={<CustomTooltip currencySymbol={currencySymbol} />}
                  animationDuration={0}
              />
              <Legend
                  verticalAlign="top"
                  height={36}
                  formatter={() => 'Harga Penutupan'}
              />
              <Brush
                  dataKey="Date"
                  height={30}
                  stroke="#8884d8"
                  tickFormatter={formatXAxis}
                  startIndex={Math.max(0, chartData.length - 60)} // Default tampilkan 60 titik data terakhir
              />
              
              {/* Garis referensi harga awal */}
              <ReferenceLine 
                y={chartData[0]?.Close} 
                stroke="#666" 
                strokeDasharray="3 3" 
                label={{ 
                  value: `Awal: ${formatCurrency(chartData[0]?.Close, currencySymbol)}`,
                  position: 'left',
                  fill: '#666',
                  fontSize: 11
                }} 
              />
              
              {/* Render masing-masing segmen dengan warna berbeda */}
              {segments.map((segment, idx) => (
                <Line
                  key={idx}
                  data={segment.data}
                  type="monotone"
                  dataKey="Close"
                  name={`Segment-${idx}`}
                  stroke={segment.isPositive ? '#4CAF50' : '#E53935'}
                  dot={false}
                  activeDot={{ r: 6 }}
                  strokeWidth={2}
                  connectNulls
                  isAnimationActive={false}
                  legendType="none"
                />
              ))}
              
              {/* Garis utama yang tidak terlihat (untuk tooltip) */}
              <Line
                type="monotone"
                dataKey="Close"
                name="Harga Penutupan"
                stroke="transparent"
                dot={<CustomizedDot />}
                activeDot={{ r: 6 }}
                strokeWidth={0}
              />
            </LineChart>
          </ResponsiveContainer>
          
          {/* Informasi kinerja total */}
          <div style={{
            position: 'absolute',
            top: 0,
            right: 30,
            backgroundColor: 'rgba(255,255,255,0.8)',
            padding: '5px 10px',
            borderRadius: '4px',
            fontSize: '13px',
            border: '1px solid #ddd'
          }}>
            {(() => {
              const firstPrice = chartData[0]?.Close || 0;
              const lastPrice = chartData[chartData.length - 1]?.Close || 0;
              const change = lastPrice - firstPrice;
              const percentChange = (change / firstPrice) * 100;
              const isPositive = change >= 0;
              
              return (
                <>
                  <div style={{ fontWeight: 'bold', marginBottom: '3px' }}>Kinerja Total:</div>
                  <div style={{ color: isPositive ? '#4CAF50' : '#E53935' }}>
                    {isPositive ? '+' : ''}{formatCurrency(change, currencySymbol)} ({isPositive ? '+' : ''}{percentChange.toFixed(2)}%)
                  </div>
                </>
              );
            })()}
          </div>
        </div>
      </div>
  );
};

export default StockChart;
